INSERT INTO items (slug, category, data, published, sort, updated_at) VALUES ('wheel-9evo-7x17-et43', 'precision', '{"slug":"wheel-9evo-7x17-et43","category":"precision","title":{"pl":"Felga 7J×17 ET43 5×100 według rysunku","ru":"Диск 7J×17 ET43 5×100 по чертежу","en":"Wheel 7J×17 ET43 5×100 from the drawing"},"summary":{"pl":"Test jądra Monge: felga odlewana zbudowana według rysunku fabrycznego — 20 okien, wklęsły front, gniazda śrub i zaokrąglenia. Bryła bez błędów topologii.","ru":"Проверка ядра Monge: литой диск по заводскому чертежу — 20 окон, вогнутая лицевая часть, колодцы под болты и скругления. Тело без ошибок топологии.","en":"A Monge kernel test: a cast wheel built from the factory drawing — 20 windows, a dished face, bolt pockets and fillets. A solid with no topology errors."},"material":{"pl":"Stop aluminium AlSi7Mg","ru":"Алюминиевый сплав AlSi7Mg","en":"Aluminium alloy AlSi7Mg"},"dimensions":"Ø471 × 210 mm","massKg":10.1,"faces":562,"version":"0.3","image":"/library/wheel-9evo-7x17-et43/render.webp","model":"/library/wheel-9evo-7x17-et43/model.glb","finish":"satin","view":[-28,12],"files":[{"format":"GLB","href":"/library/wheel-9evo-7x17-et43/model.glb","access":"free"},{"format":"STEP","href":"models/wheel-9evo-7x17-et43/wheel-9evo-7x17-et43.step","access":"pro"}],"updated":"2026-10-05","rotate":[90,0,0]}', 1, 30, '2026-10-05')
