INSERT INTO items (slug, category, data, published, sort, updated_at) VALUES ('nut-m12x1-5-closed', 'fasteners', '{"slug":"nut-m12x1-5-closed","category":"fasteners","title":{"pl":"Nakrętka zamknięta M12×1,5, klucz 19","ru":"Гайка закрытая M12×1,5, ключ 19","en":"Closed wheel nut M12×1.5, 19 mm hex"},"summary":{"pl":"Nakrętka kołpakowa ze stożkiem 60°, gwint M12×1,5. Część zestawu do felgi.","ru":"Колпачковая гайка с конусом 60°, резьба M12×1,5. Деталь из комплекта к диску.","en":"A cap nut with a 60° seat and M12×1.5 thread, part of the wheel set."},"material":{"pl":"Stal","ru":"Сталь","en":"Steel"},"dimensions":"25 × 30 mm","faces":430,"version":"0.3","image":"/library/nut-m12x1-5-closed/render.webp","model":"/library/nut-m12x1-5-closed/model.glb","finish":"steel","view":[-30,28],"files":[{"format":"GLB","href":"/library/nut-m12x1-5-closed/model.glb","access":"free"},{"format":"STEP","href":"models/nut-m12x1-5-closed/nut-m12x1-5-closed.step","access":"pro"}],"updated":"2026-10-05"}', 1, 40, '2026-10-05')
