INSERT INTO items (slug, category, data, published, sort, updated_at) VALUES ('centering-ring-75-57-1', 'precision', '{"slug":"centering-ring-75-57-1","category":"precision","title":{"pl":"Pierścień centrujący 75 → 57,1","ru":"Центрирующее кольцо 75 → 57,1","en":"Hub-centric ring 75 → 57.1"},"summary":{"pl":"Pierścień dopasowujący otwór centralny felgi Ø75 do piasty Ø57,1.","ru":"Кольцо переходит с центрального отверстия диска Ø75 на ступицу Ø57,1.","en":"Adapts a Ø75 wheel centre bore to a Ø57.1 hub."},"material":{"pl":"Tworzywo sztuczne","ru":"Пластик","en":"Plastic"},"dimensions":"Ø77 × 10.5 mm","faces":6,"version":"0.3","image":"/library/centering-ring-75-57-1/render.webp","model":"/library/centering-ring-75-57-1/model.glb","finish":"source","view":[-25,40],"files":[{"format":"GLB","href":"/library/centering-ring-75-57-1/model.glb","access":"free"},{"format":"STEP","href":"models/centering-ring-75-57-1/centering-ring-75-57-1.step","access":"pro"}],"updated":"2026-10-05"}', 1, 50, '2026-10-05')
